import{z as A,x as d,o as a,c as p,q as t,j as s,D as E,d as r,s as n,S as l,b as i}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"服务发现","description":"","frontmatter":{"title":"服务发现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/orch-service-discovery.md","filePath":"cs/orch-service-discovery.md","lastUpdated":1791413859000}'),c={name:"cs/orch-service-discovery.md"};function B(D,e,S,C,P,h){const o=d("Mermaid");return a(),p("div",null,[e[2]||(e[2]=t('<h1 id="服务发现" tabindex="-1">服务发现 <a class="header-anchor" href="#服务发现" aria-label="Permalink to &quot;服务发现&quot;">​</a></h1><div class="epigraph"><p>ClusterIP 是一句被所有人共同维持的谎言：那个地址不在任何网卡上，它只活在每个节点的转发规则里。</p><footer>—— 据 Kubernetes 官方文档（Service、EndpointSlice、kube-proxy）整理</footer></div><p><a href="/cs/orch-declarative-controller">上一课</a>把调和循环钉成 spec/status 加水平触发，本课看它的第一个成品。主干课 <a href="/cs/service-discovery">服务发现</a> 给过三条路（DNS、注册表、网格）与核心缺口——实例上下线比 DNS TTL 快；本课拆 Kubernetes 怎么把「发现」也写成控制循环：Service 的标签选择器、端点的分片、每台节点上的转发规则，谁在什么延迟内把它们对齐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>pod 秒级生灭，IP 随生灭变化；访问方要的是一个稳定的名字与地址。Service 给了名字加一个虚 IP，加一个标签选择器。缺口在中间那段：谁把「选择器命中的 pod 集合」变成「每台节点上都生效的转发规则」，端点变更到规则生效要多久、规模大了会不会拖垮控制面。发现错了的错法很具体：流量打进已死的 pod，或者活着的 pod 一直分不到流量。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>链上有两个循环。第一个：端点控制器 watch pod 与 Service，算选择器交集，把结果写进 EndpointSlice——按量分片，默认每片百个端点上下；pod 的 readiness 决定它进不进片。第二个：每台节点上的 kube-proxy watch EndpointSlice，在本机写转发规则：iptables 模式逐条写网络地址转换规则，IPVS 模式维护哈希表。DNS（CoreDNS）把服务名解到虚 IP；无头服务跳过虚 IP，直接解到 pod IP 清单——给客户端自己做均衡的场景。</p><p><span class="marginnote">术语翻译：ClusterIP 是一段「不存在于任何网卡上的地址」——没有进程监听它，它只是每台节点转发规则里的一个匹配条件；说「连上 ClusterIP」，真实发生的事是你的包在本节点被改写了目的地。</span></p>',8)),(a(),s(l,null,{default:E(()=>[n(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SVC%5B%22Service%20%E9%80%89%E6%8B%A9%E5%99%A8%22%5D%20--%3E%20EPC%5B%22%E7%AB%AF%E7%82%B9%E6%8E%A7%E5%88%B6%E5%99%A8%20reconcile%22%5D%0A%20%20EPC%20--%3E%20SLICE%5B%22EndpointSlice%20%E5%88%86%E7%89%87%22%5D%0A%20%20SLICE%20--%3E%20PROXY%5B%22%E6%AF%8F%E8%8A%82%E7%82%B9%20kube-proxy%20watch%22%5D%0A%20%20PROXY%20--%3E%20RULES%5B%22iptables%20%E6%88%96%20IPVS%20%E8%A7%84%E5%88%99%22%5D%0A%20%20RULES%20--%3E%20DNAT%5B%22DNAT%20%E5%88%B0%E6%9F%90%E4%B8%AA%20pod%22%5D%0A%20%20DNS%5B%22CoreDNS%3A%20%E5%90%8D%E5%AD%97%E8%A7%A3%E5%88%B0%E8%99%9A%20IP%22%5D%20--%3E%20CLIENT%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%0A%20%20CLIENT%20--%3E%20DNAT%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i("h2",{id:"机制",tabindex:"-1"},[r("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=i("p",null,"虚 IP 只存在于规则里：没有任何进程监听它，包到节点上被规则改写目的地——这是「共同维持的谎言」的机制化。规模的真实分水岭在查表复杂度：iptables 的规则是线性链，端点到几千个时全量规则的重放与逐条匹配都成为瓶颈；IPVS 换成哈希表，查表近常数——这是官方文档在大规模场景下推荐 IPVS 的理由，不是玄学。连接跟踪记住第一次转换的目的地，让后续包走同一条路；代价是 UDP 这类无连接协议的跟踪项有老化时间，后端换掉后旧会话仍往旧地址打——发现的正确性与会话亲和在此打架，靠超时与主动清表权衡。",-1)),(a(),s(l,null,{default:E(()=>[n(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20PKT%5B%22%E5%8C%85%E5%8F%91%E5%BE%80%E8%99%9A%20IP%20%E4%B8%8E%E7%AB%AF%E5%8F%A3%22%5D%20--%3E%20PICK%7B%22%E8%8A%82%E7%82%B9%E8%BD%AC%E5%8F%91%E8%A7%84%E5%88%99%E6%9F%A5%E8%A1%A8%22%7D%0A%20%20PICK%20--%3E%20SEL%5B%22%E6%8C%89%E8%B4%9F%E8%BD%BD%E5%9D%87%E8%A1%A1%E6%8C%91%E4%B8%80%E4%B8%AA%E5%90%8E%E7%AB%AF%22%5D%0A%20%20SEL%20--%3E%20DNAT%5B%22DNAT%3A%20%E7%9B%AE%E7%9A%84%E5%9C%B0%E6%94%B9%E5%86%99%E6%88%90%20Pod%20IP%22%5D%0A%20%20DNAT%20--%3E%20CT%5B%22conntrack%20%E8%AE%B0%E4%B8%8B%E9%A6%96%E6%AC%A1%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20CT%20--%3E%20FWD%5B%22%E8%BD%AC%E5%8F%91%E7%BB%99%E5%90%8E%E7%AB%AF%20Pod%22%5D%0A%20%20NEXT%5B%22%E5%90%8C%E8%BF%9E%E6%8E%A5%E7%9A%84%E5%90%8E%E7%BB%AD%E5%8C%85%22%5D%20--%3E%20CTQ%7B%22conntrack%20%E6%9C%89%E8%AE%B0%E5%BD%95%3F%22%7D%0A%20%20CTQ%20--%3E%7C%22%E6%9C%89%22%7C%20SAME%5B%22%E8%B5%B0%E5%90%8C%E4%B8%80%E6%9D%A1%E8%B7%AF%2C%20%E4%B8%8D%E9%87%8D%E6%96%B0%E9%80%89%E5%90%8E%E7%AB%AF%22%5D%0A%20%20CTQ%20--%3E%7C%22%E8%AE%B0%E5%BD%95%E8%80%81%E5%8C%96%E6%88%96%E8%A2%AB%E6%B8%85%22%7C%20PICK%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=t('<p><span class="marginnote">数字实例：后端扩到 3000 个 pod 时，iptables 模式每条规则线性排链、加一条规则要整链重放；IPVS 用哈希表，查表仍是几次比较——同样 3000 个后端，规模分水岭就在「线性链对哈希」这一步，这也是大规模集群换 IPVS 的直接理由。</span></p><p>EndpointSlice 的分片让传播量有界：没有分片时一个端点抖动，全部 kube-proxy 都要重读全表；分片后只有相关分片变更。 readiness 把健康检查接进发现：探针不过的 pod 不进片——这根线是下一课滚动发布的命脉。</p><p><span class="marginnote">容器里 DNS 慢的经典来源在解析器配置：默认 ndots 为 5，短名字（点不足五个）会先补各搜索后缀轮番试错，每次失败都是一轮往返；对高频调用的服务名，这是白付的延迟。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课是三层的发现与转发；七层的路由、重试、熔断是服务网格的事，失败流量的治理见 <a href="/cs/rate-limit-circuit-breaker">限流与熔断</a>。发现是最终一致的：端点变更到全部节点的规则生效有传播延迟，具体怎么利用这段延迟安全换版本，是下一课的题。本课不写网格与多集群。</p><p><span class="marginnote">常见误区：初学者容易以为 Service 换后端是瞬时生效。端点变更要经控制器写 EndpointSlice、再传到每台节点的 kube-proxy 重写规则，全程有秒级传播延迟；刚死掉的 pod 地址可能仍被转发几秒——这也是退场要先「摘端点、再停进程」的原因（下一课的合同）。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>发现被写成两个循环：选择器收敛到 EndpointSlice，EndpointSlice 收敛到节点转发规则。</li><li>虚 IP 只在规则里存在；查表复杂度（线性链对哈希）才是规模分水岭。</li><li>连接跟踪换来会话亲和，也带来 UDP 换后端的陈旧会话问题。</li><li>分片与 readiness 是控制面传播量与健康门控的两根杠杆。</li><li>出处：Kubernetes 官方文档（Service、EndpointSlice、kube-proxy）；主干课服务发现。</li></ul>',8))])}const m=A(c,[["render",B]]);export{T as __pageData,m as default};
